import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.3 プレリリース","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.3 プレリリース","docId":"releases.4.2.1-rc.3","translationKey":"releases.4.2.1-rc.3","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","translationRevision":"0e5cfa422162e46fbcef7b3d6f53a911290810f16ef500a65fdfb72901a86ca1","order":30},"headers":[],"relativePath":"ja/releases/4.2.1-rc.3.md","filePath":"ja/releases/4.2.1-rc.3.md","lastUpdated":1794611623000}'),c={name:"ja/releases/4.2.1-rc.3.md"};function l(i,e,s,d,n,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="tiktools-421-rc3" tabindex="-1">TikTools 4.2.1-rc.3 <a class="header-anchor" href="#tiktools-421-rc3" aria-label="Permalink to &quot;TikTools 4.2.1-rc.3 {#tiktools-421-rc3}&quot;">​</a></h1><h2 id="goal-release-status-and-prerequisites" tabindex="-1">目的・公開状況・前提条件 <a class="header-anchor" href="#goal-release-status-and-prerequisites" aria-label="Permalink to &quot;目的・公開状況・前提条件 {#goal-release-status-and-prerequisites}&quot;">​</a></h2><p>2026年11月13日の報告では RC3 は公開済みプレリリースです。バックアップと別のテストプロファイルを用意し、RC2 後の Linux デスクトップ変更を評価します。安定チャンネルの更新ではなく候補版です。<a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">リリース一覧</a> から公開 AppImage、DEB、可搬型アセットと <code>SHA256SUMS.txt</code> を取得します。記録されたパッケージはローカルで作成されました。</p><p>Cloud セクションの復旧と共同操作は実験段階です。インストールではバックエンド移行を配置せず、本番アカウントの互換性も証明しません。</p><h2 id="changes-available-in-rc3" tabindex="-1">RC3 で利用できる変更 <a class="header-anchor" href="#changes-available-in-rc3" aria-label="Permalink to &quot;RC3 で利用できる変更 {#changes-available-in-rc3}&quot;">​</a></h2><ul><li>RC2 の並行比較読み取り修正と、ネイティブ失敗理由を示すローカル再試行を維持します。</li><li>変数はテキスト、数値、真偽値、リスト、ローカルシークレットを永続化します。原子的保存はホスト変更や古い編集リビジョンを拒否し、既存のテンプレート文字列描画を保ちます。</li><li>秘密はマスクされたままです。ホスト切替で旧書き込みへ戻ることはなく、ネイティブ分類は秘密になる前に待機列へ入った値も後の公開・比較から除外します。</li><li>ネイティブ変数橋渡しはキャッシュ比較、1変数の明示採用、キャッシュだけの取得に対応します。アプリはセッション、同意、ローカルリビジョン、キャッシュ項目を再検査します。</li></ul><p>変数の保存はローカルのままです。RC3 は確認付き送信・取り下げと保留競合処理を備える完全な変数変更ボタンを公開しません。その統合は <a href="./4.2.2.html">4.2.2 のソースノート</a> にあります。ローカル値を秘密にしても以前公開した Cloud コピーは消えません。</p><h2 id="check-the-published-candidate" tabindex="-1">公開候補を確認する <a class="header-anchor" href="#check-the-published-candidate" aria-label="Permalink to &quot;公開候補を確認する {#check-the-published-candidate}&quot;">​</a></h2><ol><li>チェックサムと表示 <code>4.2.1-rc.3</code> を確認します。テストプロファイルと XDG ディレクトリを通常環境から分離します。</li><li><code>demoGreeting = &quot;こんにちは&quot;</code> など無害なテキスト変数を作り、保存・再読込します。他の明示的な型も機密性のない値で確認します。</li><li>変更の読み込み・ローカル再試行を試します。設定/チームと任意のガイドを確認し、バックエンド機能不足を設定成功と扱いません。</li><li>失敗は正確な操作、版、ネイティブ理由、要求 ID を報告します。トークン、招待コード、秘密値を含めません。</li></ol><h2 id="expected-result-evidence-and-recovery" tabindex="-1">期待される結果・証拠・復旧 <a class="header-anchor" href="#expected-result-evidence-and-recovery" aria-label="Permalink to &quot;期待される結果・証拠・復旧 {#expected-result-evidence-and-recovery}&quot;">​</a></h2><p>型付きローカル値は再読込後も残り、古いホスト・リビジョンの編集は明確に失敗するはずです。原記録はネイティブ変数・同期・整合性検査、偽ホストのブラウザーテスト、分離 CLI 検証、インストーラー内容、空の分離プロファイルでの frontend-ready 起動を報告します。サインイン済み本番同期やメディア再生の証拠ではありません。</p><p>AppImage の記録 SHA-256 は <code>4b11260836457350debf2680b230c52cea8408ddf17ccdc729d0025a62149b7e</code> です。取得物の添付チェックサムを確認します。失敗時はコピーしたプロファイルを保ち、復旧を再試行する前に<a href="./../user/preferences/troubleshooting.html">トラブルシューティング</a> を使います。</p><p>ニックネーム招待にはバックエンド <code>6a69c99</code> と移行 <code>20261113000001_remote_invitation_recipients.sql</code> が必要です。旧記録では人物ルート不足が観測されましたが、ここで新しい本番検査を行ったとは主張しません。自動化の Cloud 通信、オーバーレイリビジョン、残りの共同操作監査は未完了で、過去の SQLite ロック保持者も不明でした。</p><p><a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.3.md" target="_blank" rel="noreferrer">元のリリース記録</a> は日付付き証拠として保持されています。<a href="./">リリース一覧に戻る</a>。</p>',14)])])}const f=a(c,[["render",l]]);export{u as __pageData,f as default};
